function validate([classes, extraStudents]) {
  if (classes.length < 1 || classes.length > 100000) return 'classes needs 1 to 100000 entries.';
  for (const entry of classes) {
    if (!Array.isArray(entry) || entry.length !== 2) return 'Each class is [pass, total].';
    const [pass, total] = entry;
    if (!Number.isInteger(pass) || !Number.isInteger(total) || pass < 1 || pass > total || total > 100000) return 'Each class needs 1 <= pass <= total <= 100000.';
  }
  if (!Number.isInteger(extraStudents) || extraStudents < 1 || extraStudents > 100000) return 'extraStudents is between 1 and 100000.';
  return null;
}

