function maxAverageRatio(classes, extraStudents) {
  const gain = (pass, total) => (pass + 1) / (total + 1) - pass / total;
  const heap = classes.map(([pass, total]) => [gain(pass, total), pass, total]);

  function siftDown(index) {
    while (true) {
      const left = 2 * index + 1;
      const right = left + 1;
      let largest = index;
      if (left < heap.length && heap[left][0] > heap[largest][0]) {
        largest = left;
      }
      if (right < heap.length && heap[right][0] > heap[largest][0]) {
        largest = right;
      }
      if (largest === index) {
        return;
      }
      [heap[index], heap[largest]] = [heap[largest], heap[index]];
      index = largest;
    }
  }

  for (let i = Math.floor(heap.length / 2) - 1; i >= 0; i--) {
    siftDown(i);
  }
  for (let student = 0; student < extraStudents; student++) {
    const [, pass, total] = heap[0];
    heap[0] = [gain(pass + 1, total + 1), pass + 1, total + 1];
    siftDown(0);
  }
  let sum = 0;
  for (const [, pass, total] of heap) {
    sum += pass / total;
  }
  return sum / heap.length;
}

