function maxAverageRatio(classes, extraStudents) {
  // Exact allocation by dynamic programming: best[k] is the largest sum of ratios over the classes
  // seen so far when k extra students have been placed among them, trying every count for each class.
  let best = new Array(extraStudents + 1).fill(-Infinity);
  best[0] = 0;
  for (const [p, t] of classes) {
    const next = new Array(extraStudents + 1).fill(-Infinity);
    for (let k = 0; k <= extraStudents; k++) {
      for (let add = 0; add <= k; add++) {
        if (best[k - add] === -Infinity) continue;
        next[k] = Math.max(next[k], best[k - add] + (p + add) / (t + add));
      }
    }
    best = next;
  }
  return best[extraStudents] / classes.length;
}

