function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const make = (count, maxTotal) => Array.from({ length: count }, () => {
    const total = 1 + pick(maxTotal);
    return [1 + pick(total), total];
  });
  if (size === 'large') {
    const maxTotal = [10, 1000, 100000][pick(3)];
    const extra = [1 + pick(2000), 20000 + pick(20000), 100000][pick(3)];
    return [make(2000, maxTotal), extra];
  }
  return [make(1 + pick(5), 1 + pick(9)), 1 + pick(8)];
}
